import android.app.Activity;
import org.json.JSONObject;
import java.util.Map;
import com.revenuecat.purchases.Purchases;
import com.revenuecat.purchases.PurchasesConfiguration;
import com.revenuecat.purchases.common.PlatformInfo;
import com.revenuecat.purchases.hybridcommon.CommonKt;
import com.revenuecat.purchases.hybridcommon.OnResult;
import com.revenuecat.purchases.hybridcommon.ErrorContainer;
import com.revenuecat.purchases.hybridcommon.mappers.MappersHelpersKt;

gameActivityClassAdditions.insert:
// ===== RevenueCat bridge =====
public native void nativeRevenueCatOnResult(long callbackId, String json, boolean isError);

private OnResult RevenueCat_makeResult(final long callbackId) {
	return new OnResult() {
		@Override public void onReceived(Map<String, ?> map) {
			try {
				nativeRevenueCatOnResult(callbackId, MappersHelpersKt.convertToJson(map).toString(), false);
			} catch (Throwable t) {
				nativeRevenueCatOnResult(callbackId, "{\"code\":-1,\"message\":\"" + t.getMessage() + "\"}", true);
			}
		}
		@Override public void onError(ErrorContainer errorContainer) {
			try {
				nativeRevenueCatOnResult(callbackId, MappersHelpersKt.convertToJson(errorContainer.getInfo()).toString(), true);
			} catch (Throwable t) {
				nativeRevenueCatOnResult(callbackId, "{\"code\":-1,\"message\":\"error\"}", true);
			}
		}
	};
}

// Never swallow failures: log them to logcat (tag "RevenueCat") and surface them to the caller.
private String RevenueCat_errJson(Throwable t) {
	String msg = (t == null) ? "unknown error" : String.valueOf(t);
	msg = msg.replace("\\", "\\\\").replace("\"", "'");
	android.util.Log.e("RevenueCat", "call failed: " + msg);
	return "{\"code\":-1,\"message\":\"" + msg + "\"}";
}

public void AndroidThunkJava_RevenueCat_Configure(final String apiKey, final String appUserId) {
	final String uid = (appUserId != null && appUserId.length() > 0) ? appUserId : null;
	runOnUiThread(new Runnable() { public void run() {
		if (apiKey == null || apiKey.length() == 0) {
			android.util.Log.e("RevenueCat", "Configure failed: API key is empty. Set 'Google Api Key' in Project Settings / Plugins / RevenueCat.");
			return;
		}
		try {
			Purchases.setPlatformInfo(new PlatformInfo("unreal", "0.1.0"));
			PurchasesConfiguration.Builder builder =
				new PurchasesConfiguration.Builder(getApplicationContext(), apiKey);
			if (uid != null) { builder.appUserID(uid); }
			Purchases.configure(builder.build());
			android.util.Log.i("RevenueCat", "Configure OK, appUserId=" + uid);
		} catch (Throwable t) {
			android.util.Log.e("RevenueCat", "Configure failed", t);
		}
	}});
}

public void AndroidThunkJava_RevenueCat_GetOfferings(final long callbackId) {
	try { CommonKt.getOfferings(RevenueCat_makeResult(callbackId)); }
	catch (Throwable t) { nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true); }
}

public void AndroidThunkJava_RevenueCat_GetCustomerInfo(final long callbackId) {
	try { CommonKt.getCustomerInfo(RevenueCat_makeResult(callbackId)); }
	catch (Throwable t) { nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true); }
}

public void AndroidThunkJava_RevenueCat_RestorePurchases(final long callbackId) {
	try { CommonKt.restorePurchases(RevenueCat_makeResult(callbackId)); }
	catch (Throwable t) { nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true); }
}

public void AndroidThunkJava_RevenueCat_LogIn(final String appUserId, final long callbackId) {
	try { CommonKt.logIn(appUserId, RevenueCat_makeResult(callbackId)); }
	catch (Throwable t) { nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true); }
}

public void AndroidThunkJava_RevenueCat_LogOut(final long callbackId) {
	try { CommonKt.logOut(RevenueCat_makeResult(callbackId)); }
	catch (Throwable t) { nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true); }
}

public void AndroidThunkJava_RevenueCat_PurchasePackage(final String packageIdentifier, final String offeringIdentifier, final long callbackId) {
	final Activity activity = this;
	runOnUiThread(new Runnable() { public void run() {
		try {
			java.util.HashMap<String, Object> presentedOfferingContext = new java.util.HashMap<String, Object>();
			if (offeringIdentifier != null && offeringIdentifier.length() > 0) {
				presentedOfferingContext.put("offeringIdentifier", offeringIdentifier);
			}
			CommonKt.purchasePackage(
				activity,
				packageIdentifier,
				presentedOfferingContext,
				null,   // googleOldProductId
				null,   // googleReplacementMode
				null,   // googleIsPersonalizedPrice
				RevenueCat_makeResult(callbackId));
		} catch (Throwable t) {
			nativeRevenueCatOnResult(callbackId, RevenueCat_errJson(t), true);
		}
	}});
}
// ===== end RevenueCat bridge =====
